        ai_script = '''<script>const aiRequest=document.querySelector('#ai-request'),aiAnalyze=document.querySelector('#ai-analyze'),aiChat=document.querySelector('#ai-chat');const aiLabels={requested_amount:'Purchase amount',current_balance:'Available balance',essential_monthly_expenses:'Essential monthly expenses',minimum_balance:'Balance to protect',confirmed_monthly_income:'Confirmed monthly income',income_date:'Next income date'};aiAnalyze.onclick=async()=>{const text=aiRequest.value.trim();if(!text){aiChat.innerHTML='<div class="ai-bubble">Tell me about the purchase and any financial details you already know.</div>';return}aiAnalyze.disabled=true;aiAnalyze.textContent='Understanding…';aiChat.innerHTML='<div class="ai-bubble"><b>AI guide</b><br>Reading your request and preparing one complete set of follow-up questions…</div>';try{const response=await fetch('/api/ai-intake',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text})}),result=await response.json();if(!response.ok)throw Error();const facts=result.facts||{},missing=result.missing||[];const bubble=document.createElement('div');bubble.className='ai-bubble';bubble.innerHTML='<b>AI guide</b><br>'+((result.available?'I found the details below. ':'I could not use Gemini right now, so please complete these fields. '))+(missing.length?'Please provide the remaining essentials together:':'Everything needed for a first safety check is ready.');const grid=document.createElement('div');grid.className='ai-missing';const keys=[...new Set([...Object.keys(facts),...missing.map(item=>item.key)])];keys.forEach(key=>{if(!aiLabels[key])return;const label=document.createElement('label'),input=document.createElement('input');input.name=key;input.type=key==='income_date'?'date':'number';if(key==='income_date')input.type='date';input.value=facts[key]??'';input.placeholder=aiLabels[key];label.append(aiLabels[key],input);grid.append(label)});const use=document.createElement('button');use.type='button';use.textContent='Use these details in Decision check';use.onclick=()=>{[...grid.querySelectorAll('input')].forEach(input=>{const target=assessmentForm.elements[input.name];if(target&&input.value)target.value=input.value});selectWorkspace('decision-check')};aiChat.replaceChildren(bubble,grid,use)}catch{aiChat.innerHTML='<div class="ai-bubble">I could not process that request. You can still use Decision check directly.</div>'}finally{aiAnalyze.disabled=false;aiAnalyze.textContent='Understand my request'}};</script>'''
        profile_script = '''<script>const aiGuest=document.querySelector('#ai-guest'),aiExisting=document.querySelector('#ai-existing'),aiProfilePicker=document.querySelector('#ai-profile-picker'),aiProfileSearch=document.querySelector('#ai-profile-search'),aiLoadProfile=document.querySelector('#ai-load-profile'),aiProfileStatus=document.querySelector('#ai-profile-status');window.aiProfileFacts={};function setAiMode(existing){aiGuest.setAttribute('aria-pressed',String(!existing));aiExisting.setAttribute('aria-pressed',String(existing));aiProfilePicker.hidden=!existing;if(!existing){window.aiProfileFacts={};aiProfileStatus.textContent='Guest mode — enter details in your own words.'}}aiGuest.onclick=()=>setAiMode(false);aiExisting.onclick=()=>setAiMode(true);aiLoadProfile.onclick=async()=>{const userId=aiProfileSearch.value.trim().split(' ')[0];if(!userId)return;aiLoadProfile.disabled=true;try{const response=await fetch('/api/ai-profile?user_id='+encodeURIComponent(userId)),data=await response.json();if(!response.ok)throw Error();window.aiProfileFacts=data.facts||{};Object.entries(window.aiProfileFacts).forEach(([key,value])=>{const field=assessmentForm.elements[key];if(field)field.value=value});aiProfileStatus.textContent='Loaded '+data.user_id+' · verified balance, reserve, and currency are prefilled.'}catch{aiProfileStatus.textContent='That profile was not found. Search a loaded user ID.'}finally{aiLoadProfile.disabled=false}};new MutationObserver(()=>{const grid=aiChat.querySelector('.ai-missing');if(!grid)return;Object.entries(window.aiProfileFacts).forEach(([key,value])=>{const input=grid.querySelector('[name="'+key+'"]');if(input&&!input.value)input.value=value})}).observe(aiChat,{childList:true,subtree:true});</script>'''
        upload_script = r'''<script>const aiEvidenceFile=document.querySelector('#ai-evidence-file'),aiEvidenceStatus=document.querySelector('#ai-evidence-file-status');aiEvidenceFile.onchange=()=>{const file=aiEvidenceFile.files&&aiEvidenceFile.files[0];if(!file)return;if(file.size>4*1024*1024){aiEvidenceStatus.textContent='Choose a file smaller than 4 MB.';return}aiEvidenceStatus.textContent='Reading '+file.name+'…';const reader=new FileReader();reader.onload=async()=>{try{const data=String(reader.result).split(',')[1]||'';const response=await fetch('/api/ai-evidence',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:file.name,data})}),result=await response.json();if(!response.ok)throw Error();aiRequest.value=(aiRequest.value?aiRequest.value+'\n\n':'')+'Supporting evidence from '+file.name+':\n'+result.text;aiEvidenceStatus.textContent='Evidence read and added for AI review. You can edit the request before continuing.'}catch{aiEvidenceStatus.textContent='Could not read that file. Try a clear PNG, JPG, WEBP, or TXT file.'}};reader.readAsDataURL(file)};</script>'''
